import { useQuery } from "@tanstack/react-query";
import { Outlet, useNavigate, useParams } from "react-router";
import { Sidebar } from "../components/Sidebar/Sidebar";
import { trackEvent } from "../lib/analytics";
import { getSitesQueryOptions } from "../queries/sites/sites-query";
import css from "./Layout.module.css";

/** The persistent shell every route renders inside: the sidebar plus whichever page is current. */
export function Layout() {
  const { siteSlug = "" } = useParams();
  const navigate = useNavigate();
  const sitesQuery = useQuery(getSitesQueryOptions());

  function switchSite(slug: string) {
    trackEvent("Site switched", { from_site: siteSlug, to_site: slug });
    navigate(`/sites/${slug}/posts`);
  }

  return (
    <div className={css.shell}>
      <Sidebar sites={sitesQuery.data ?? []} currentSiteSlug={siteSlug} onSwitchSite={switchSite} />
      <main className={css.content}>
        <Outlet />
      </main>
    </div>
  );
}
---CSS---
.shell {
  display: grid;
  /* The sidebar column is fluid so it shrinks with the viewport — its own
     container query in Sidebar.module.css is what decides when that
     shrinking should also change its layout, not this rule. */
  grid-template-columns: clamp(3.5rem, 16vw, 15rem) 1fr;
  min-height: 100dvh;
}

.content {
  min-width: 0;
  padding: 2rem 2.5rem;
}
---SIDEBAR---
import { render } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import type { Site } from "../../types";
import { Sidebar } from "./Sidebar";

const SITES: readonly Site[] = [
  { id: 1, name: "Acme Blog", slug: "acme", deployHookUrl: "https://hooks.example.invalid/acme" },
  {
    id: 2,
    name: "Northwind Notes",
    slug: "northwind",
    deployHookUrl: "https://hooks.example.invalid/nw",
  },
];

// The container query in Sidebar.module.css reacts to the sidebar's own box,
// not the browser viewport, so the two cases below give it a fixed-width
// wrapper directly rather than resizing the page. Resizing the viewport would
// pass for the wrong reason here and fail the moment the sidebar is rendered
// anywhere narrower than the window.
function renderInside(widthPx: number) {
  return render(
    <div style={{ width: `${widthPx}px` }}>
      <Sidebar sites={SITES} currentSiteSlug="acme" onSwitchSite={vi.fn()} />
    </div>,
  );
}

describe("Sidebar", () => {
  it("shows the nav label text when its container is wide", async () => {
    const { getByText } = renderInside(320);

    const label = getByText("Posts");
    await expect.poll(() => getComputedStyle(label).display).not.toBe("none");
  });

  it("hides the nav label and centers the icon when its container is narrow", async () => {
    const { getByText } = renderInside(140);

    const label = getByText("Posts");
    await expect.poll(() => getComputedStyle(label).display).toBe("none");
  });

  it("always exposes the site switcher, in both tiers", async () => {
    const wide = renderInside(320);
    expect(wide.getByRole("combobox")).toBeInTheDocument();
    wide.unmount();

    const narrow = renderInside(140);
    expect(narrow.getByRole("combobox")).toBeInTheDocument();
  });

  it("calls onSwitchSite with the newly selected site's slug", async () => {
    const onSwitchSite = vi.fn();
    const { getByRole } = render(
      <div style={{ width: "320px" }}>
        <Sidebar sites={SITES} currentSiteSlug="acme" onSwitchSite={onSwitchSite} />
      </div>,
    );

    const select = getByRole("combobox") as HTMLSelectElement;
    select.value = "northwind";
    select.dispatchEvent(new Event("change", { bubbles: true }));

    expect(onSwitchSite).toHaveBeenCalledWith("northwind");
  });
});
import type { Site } from "../../types";
import css from "./Sidebar.module.css";

interface SidebarProps {
  readonly sites: readonly Site[];
  readonly currentSiteSlug: string;
  readonly onSwitchSite: (slug: string) => void;
}

/**
 * The persistent shell nav: a site switcher plus the (currently one-item)
 * section nav. Its layout is driven entirely by its own container width —
 * see Sidebar.module.css — not the viewport, so it re-tiers correctly
 * whatever width the surrounding shell actually gives it.
 */
export function Sidebar({ sites, currentSiteSlug, onSwitchSite }: SidebarProps) {
  return (
    <nav className={css.sidebar} aria-label="Site">
      <label className={css.switcherLabel}>
        <span className={css.srOnly}>Switch site</span>
        <select
          className={css.switcherSelect}
          value={currentSiteSlug}
          onChange={(event) => onSwitchSite(event.target.value)}
        >
          {sites.map((site) => (
            <option key={site.slug} value={site.slug}>
              {site.name}
            </option>
          ))}
        </select>
      </label>

      <ul className={css.nav}>
        <li>
          <span className={css.navItem} aria-current="page">
            <span className={css.navIcon} aria-hidden="true">
              ▤
            </span>
            <span className={css.navLabel}>Posts</span>
          </span>
        </li>
      </ul>
    </nav>
  );
}

